public class Solution{string lo,hi;int c;(char,char)[]p={('0','0'),('1','1'),('6','9'),('8','8'),('9','6')};void F(char[]s,int l,int r){if(l>r){string x=new string(s);if((x.Length>lo.Length||string.CompareOrdinal(x,lo)>=0)&&(x.Length<hi.Length||string.CompareOrdinal(x,hi)<=0))c++;return;}foreach(var q in p){if(l==0&&s.Length>1&&q.Item1=='0')continue;if(l==r&&q.Item1!=q.Item2)continue;s[l]=q.Item1;s[r]=q.Item2;F(s,l+1,r-1);}}public int StrobogrammaticInRange(string low,string high){lo=low;hi=high;for(int n=lo.Length;n<=hi.Length;n++)F(new char[n],0,n-1);return c;}}
